-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in  = 5,
        gaps_out = 10,

        border_size = 2,

       col = {
    -- Active border: A solid, crisp electric purple
    active_border   = "0xffffffff", -- White
    inactive_border = "0xff808080", -- Medium Grey
},

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = true,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 10,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1,
        inactive_opacity = 0.77,

        shadow = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        blur = {
            enabled   = true,
            size      = 3,
            passes    = 1,
            vibrancy  = 0.1696,
        },
    },

    animations = {
        enabled = true,
    },
})

-- =========================================================================
-- WINDOW ANIMATIONS
-- Snappy, low-duration translations utilizing the custom "quick" curve.
-- =========================================================================
-- 1. Define the bezier curve first
hl.curve("quick", {
    type = "bezier",
    points = { {0.15, 0.85}, {0.1, 1.05} }
})

-- 2. Your animations can now use "quick"
hl.animation({
    leaf = "windows",
    enabled = true,
    speed = 1.6,
    bezier = "quick",
})

hl.animation({
    leaf = "windowsIn",
    enabled = true,
    speed = 2.5,
    bezier = "quick",
})

hl.animation({
    leaf = "windowsOut",
    enabled = true,
    speed = 2.5,
    bezier = "quick",
})

hl.animation({
    leaf = "windowsMove",
    enabled = true,
    speed = 1.6,
    bezier = "quick",
})

hl.animation({
    leaf = "workspaces",
    enabled = true,
    speed = 5.0,
    bezier = "quick",
    style = "slide",
})
